function getChangelog(){return readStoredJson(CONFIG.STORAGE_KEYS.CHANGELOG,[])}function saveChangelog(logs){localStorage.setItem(CONFIG.STORAGE_KEYS.CHANGELOG,JSON.stringify(logs))}function addChangelogEntry(type,content){const logs=getChangelog();logs.unshift({id:"log_"+Date.now(),time:new Date().toISOString(),user:AppState.user?.name||"AP\u63A5\u9F8D\u5DE5\u5177\u7CFB\u7D71",type,content}),saveChangelog(logs),document.getElementById("tab-changelog").classList.contains("active")&&renderChangelog()}function getSheetLogs(){const raw=AppState.sheetLogs||[],actionMap={\u65B0\u589E:"add",\u7DE8\u8F2F:"edit",\u522A\u9664:"delete"};return raw.map(l=>({id:`sheet_${l.memberId}_${l.date}_${l.action}`,time:`${l.date.slice(0,4)}-${l.date.slice(4,6)}-${l.date.slice(6,8)}T00:00:00`,user:l.editor,type:actionMap[l.action]||l.action,content:`#${l.memberId} ${l.memberName}`,source:"sheet"}))}function renderChangelog(dateFilter=""){const listEl=document.getElementById("changelog-list"),emptyEl=document.getElementById("changelog-empty"),localLogs=getChangelog(),sheetLogs=getSheetLogs();let logs=[...localLogs,...sheetLogs];const seen=new Set;logs=logs.filter(l=>{const key=`${l.user}_${l.type}_${l.content}`;return seen.has(key)?!1:(seen.add(key),!0)}),logs.sort((a,b)=>new Date(b.time)-new Date(a.time)),dateFilter&&(logs=logs.filter(l=>l.time.startsWith(dateFilter))),emptyEl.style.display=logs.length===0?"block":"none",listEl.style.display=logs.length===0?"none":"flex";const typeLabels={add:"\u65B0\u589E",edit:"\u7DE8\u8F2F",delete:"\u522A\u9664"};listEl.innerHTML=logs.map(l=>{const date=new Date(l.time),timeStr=date.toLocaleDateString("zh-TW")+" "+date.toLocaleTimeString("zh-TW",{hour:"2-digit",minute:"2-digit"}),sourceTag=l.source==="sheet"?' <span class="cache-badge">\u5171\u7528</span>':"";return`
      <div class="log-item">
        <span class="log-time">${timeStr}</span>
        <span class="log-user">${escapeHtml(l.user)}${sourceTag}</span>
        <span class="log-content">
          <span class="badge" style="font-size:11px;">${typeLabels[l.type]||l.type}</span>
          ${escapeHtml(l.content)}
        </span>
      </div>
    `}).join("")}function initChangelog(){const dateFilter=document.getElementById("changelog-date-filter");dateFilter.addEventListener("change",()=>{renderChangelog(dateFilter.value)}),renderChangelog()}window.initChangelog=initChangelog,window.addChangelogEntry=addChangelogEntry;
